"use strict";(globalThis.webpackChunkgsf_docusaurus_template=globalThis.webpackChunkgsf_docusaurus_template||[]).push([[5212],{2265(e){e.exports=JSON.parse('{"tag":{"label":"persona:infrastructure-engineer","permalink":"/tags/persona-infrastructure-engineer","allTagsPath":"/tags","count":13,"items":[{"id":"architecture/system-topology/choose-region-closest-to-users","title":"Choose the region that is closest to users","description":"From an energy-efficiency perspective, it\'s better to shorten the distance a network packet travels so that less energy is required to transmit it. Similarly, from an embodied-carbon perspective, when a network packet traverses through less computing equipment, we are more efficient with hardware.","permalink":"/architecture/system-topology/choose-region-closest-to-users"},{"id":"architecture/technology-selection/evaluate-other-cpu-architectures","title":"Evaluate other CPU architectures","description":"Applications are built with a software architecture that best fits the business need they are serving. Cloud providers make it easy to evaluate other CPU types","permalink":"/architecture/technology-selection/evaluate-other-cpu-architectures"},{"id":"operations/capacity-management/match-cpu-capacity-to-average-and-peak-utilization","title":"Match CPU capacity to average and peak utilization","description":"Provisioned CPU capacity has to cover peak demand, so the gap between average and peak utilization determines how much hardware sits idle. Matching CPU capacity to both average and peak utilization reduces idle resources while protecting performance at peak load.","permalink":"/operations/capacity-management/match-cpu-capacity-to-average-and-peak-utilization"},{"id":"development/minimizing-deployed-environments","title":"Minimize the total number of deployed environments","description":"In a given application, there may be a need to utilize multiple environments in the application workflow. Typically, a development environment is used for regular updates, while staging or testing enviroments are used to make sure there are no issues before code reaches a production environment where users may have access. Each added environment has an increasing energy impact, which in turn creates more emissions. As such, it is important to understand the necessity of each enviroment and it\'s environmental impact.","permalink":"/development/minimizing-deployed-environments"},{"id":"operations/optimize-edge-ai-power-performance","title":"Optimize power consumption for edge AI inference","description":"Edge AI inference workloads consume significant power on resource-constrained devices. Optimizing power-performance characteristics through dynamic workload scheduling, thermal-aware throttling, and battery-level policies reduces energy consumption and extends battery life while maintaining acceptable accuracy and latency.","permalink":"/operations/optimize-edge-ai-power-performance"},{"id":"operations/capacity-management/rightsize-compute-to-match-utilization","title":"Rightsize compute to match utilization","description":"Compute capacity that is provisioned well above what a workload actually uses wastes energy and embodied carbon. Rightsizing matches allocated compute to measured utilization, either by resizing a VM\'s resources or by moving to a better-fitting pre-configured instance type.","permalink":"/operations/capacity-management/rightsize-compute-to-match-utilization"},{"id":"architecture/system-topology/run-ai-models-edge","title":"Run AI models at the edge","description":"Deploy AI inference on edge devices or local infrastructure to reduce data transfer, network energy use, and reliance on centralised cloud compute.","permalink":"/architecture/system-topology/run-ai-models-edge"},{"id":"operations/capacity-management/scale-down-unused-applications","title":"Scale down applications when not in use","description":"Applications consume CPU even when they are not actively in use. For example, background timers, garbage collection, health checks, etc. Even when the application is shut down, the underlying hardware is consuming idle power.","permalink":"/operations/capacity-management/scale-down-unused-applications"},{"id":"operations/capacity-management/scale-down-kubernetes-workloads","title":"Scale down kubernetes applications when not in use","description":"In order to reduce carbon emissions and costs, Dev&Test Kubernetes clusters can turn off nodes out of office hours. Thereby, optimization is implemented at the cluster level. For production clusters, where nodes need to stay up and running, optimization needs to be implemented at the application level.","permalink":"/operations/capacity-management/scale-down-kubernetes-workloads"},{"id":"architecture/system-topology/efficient-hardware-ai-workloads","title":"Select efficient accelerators and instance types for AI workloads","description":"Match AI workloads to the most energy-efficient hardware accelerator or instance type to improve utilisation and reduce energy consumption per inference or training run.","permalink":"/architecture/system-topology/efficient-hardware-ai-workloads"},{"id":"operations/time-shift-kubernetes-cron-jobs","title":"Time-shift Kubernetes cron jobs","description":"The carbon emissions of a software system depends on the power consumed by that software, but also on the Carbon intensity of the electricity it is powered on. For this reason, running energy-efficient software on carbon intensive electricity grid, might be inefficient to reduce its global carbon emissions. Carbon aware time scheduling, is about scheduling workloads to execute, when electricity carbon intensity is low.","permalink":"/operations/time-shift-kubernetes-cron-jobs"},{"id":"operations/carbon-aware-ai-scheduling","title":"Use carbon-aware scheduling and region selection for AI workloads","description":"Reduce the carbon impact of AI workloads by running them in cloud regions with lower grid carbon intensity and scheduling deferrable jobs during periods of high renewable energy availability.","permalink":"/operations/carbon-aware-ai-scheduling"},{"id":"architecture/technology-selection/use-serverless","title":"Use serverless cloud services","description":"Serverless cloud services scale dynamically with demand and share infrastructure across many applications, reducing idle resource consumption and lowering embodied carbon emissions.","permalink":"/architecture/technology-selection/use-serverless"}],"unlisted":false}}')}}]);